struct Activity {
	int start, end;
};

int maxActivities(std::vector<Activity> activities) {
	int count = 0;
	for (size_t i = 0; i < activities.size(); ++i) {
		bool conflict = false;
		for (size_t j = 0; j < i; ++j) {
			if (activities[i].start < activities[j].end && activities[j].start < activities[i].end) {
				conflict = true; break;
			}
		}
		if (!conflict) count++;
	}
	return count;
}

int main() {
	std::vector<Activity> list = {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {3, 8}, {5, 9}, {6, 10}, {8, 11}, {8, 12}, {2, 13}, {12, 14}};
	std::cout << maxActivities(list) << std::endl;
	return 0;
}

