#include <iostream>
#include <vector>
#include <algorithm>

struct Activity {
	int start, end;
};

int maxActivities(std::vector<Activity> activities) {
	if (activities.empty()) return 0;
	std::sort(activities.begin(), activities.end(), [](const Activity& a, const Activity& b) {
		return a.end < b.end;
	});
	int count = 1;
	int lastEnd = activities[0].end;
	for (size_t i = 1; i < activities.size(); ++i) {
		if (activities[i].start >= lastEnd) {
			count++;
			lastEnd = activities[i].end;
		}
	}
	return count;
}

int main() {
	std::vector<Activity> list = {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {3, 8}, {5, 9}, {6, 10}, {8, 11}, {8, 12}, {2, 13}, {12, 14}};
	std::cout << maxActivities(list) << std::endl;
	return 0;
}
---
The original brute force approach fails to find the global optimum and has poor scalability. By sorting activities by end time, the greedy choice property ensures an O(N log N) solution that correctly identifies the maximum number of non-overlapping activities.

