#include <iostream>
#include <vector>
#include <algorithm>

int minPlatforms(std::vector<int> arr, std::vector<int> dep) {
	std::sort(arr.begin(), arr.end());
	std::sort(dep.begin(), dep.end());
	int n = arr.size();
	int platforms = 0, result = 0;
	int i = 0, j = 0;
	while (i < n && j < n) {
		if (arr[i] <= dep[j]) {
			platforms++; i++;
		} else {
			platforms--; j++;
		}
		result = std::max(result, platforms);
	}
	return result;
}

int main() {
	std::vector<int> arr = {900, 940, 950, 1100, 1500, 1800};
	std::vector<int> dep = {910, 1200, 1120, 1130, 1900, 2000};
	std::cout << minPlatforms(arr, dep) << std::endl;
	return 0;
}
---
The unoptimized version performs an O(N^2) double loop to check overlaps. By sorting arrivals and departures separately, we can use a two-pointer greedy scan to find the maximum concurrent events in O(N log N) time.

