struct Job {
	int id, dead, profit;
};

int scheduleJobs(std::vector<Job> jobs) {
	int totalProfit = 0;
	for (size_t i = 0; i < jobs.size(); ++i) {
		for (size_t j = i + 1; j < jobs.size(); ++j) {
			if (jobs[i].profit < jobs[j].profit) std::swap(jobs[i], jobs[j]);
		}
	}
	std::vector<int> slot(100, -1);
	for (const auto& job : jobs) {
		for (int j = job.dead - 1; j >= 0; --j) {
			if (slot[j] == -1) {
				slot[j] = job.id; totalProfit += job.profit; break;
			}
		}
	}
	return totalProfit;
}

int main() {
	std::vector<Job> jobs = {{1, 4, 20}, {2, 1, 10}, {3, 1, 40}, {4, 1, 30}};
	std::cout << scheduleJobs(jobs) << std::endl;
	return 0;
}

