#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

struct Job {
	int id, dead, profit;
};

int scheduleJobs(std::vector<Job> jobs) {
	std::sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) {
		return a.profit > b.profit;
	});
	int maxDead = 0;
	for (const auto& j : jobs) maxDead = std::max(maxDead, j.dead);
	std::set<int, std::greater<int>> freeSlots;
	for (int i = 1; i <= maxDead; ++i) freeSlots.insert(i);
	int totalProfit = 0;
	for (const auto& job : jobs) {
		auto it = freeSlots.lower_bound(job.dead);
		if (it != freeSlots.end()) {
			totalProfit += job.profit;
			freeSlots.erase(it);
		}
	}
	return totalProfit;
}

int main() {
	std::vector<Job> jobs = {{1, 4, 20}, {2, 1, 10}, {3, 1, 40}, {4, 1, 30}};
	std::cout << scheduleJobs(jobs) << std::endl;
	return 0;
}
---
The unoptimized version uses a linear search for slots, resulting in O(N * Deadlines). By using a std::set to track available slots and lower_bound for searching, we achieve O(N log D) complexity, greatly improving performance for sparse schedules.

