#include <iostream>
#include <vector>
#include <numeric>

struct Item {
	int weight, value;
};

double fractionalKnapsack(int capacity, std::vector<Item> items) {
	double totalValue = 0.0;
	std::vector<bool> used(items.size(), false);
	while (capacity > 0) {
		int bestIdx = -1;
		double maxRatio = -1.0;
		for (size_t i = 0; i < items.size(); ++i) {
			if (!used[i]) {
				double ratio = (double)items[i].value / items[i].weight;
				if (ratio > maxRatio) { maxRatio = ratio; bestIdx = i; }
			}
		}
		if (bestIdx == -1) break;
		used[bestIdx] = true;
		if (items[bestIdx].weight <= capacity) {
			capacity -= items[bestIdx].weight; totalValue += items[bestIdx].value;
		} else {
			totalValue += items[bestIdx].value * ((double)capacity / items[bestIdx].weight);
			capacity = 0;
		}
	}
	return totalValue;
}

int main() {
	std::vector<Item> items = {{10, 60}, {20, 100}, {30, 120}};
	std::cout << fractionalKnapsack(50, items) << std::endl;
	return 0;
}

output:
#include <iostream>
#include <vector>
#include <algorithm>

struct Item {
	int weight, value;
};

double fractionalKnapsack(int capacity, std::vector<Item> items) {
	std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
		return (double)a.value / a.weight > (double)b.value / b.weight;
	});
	double totalValue = 0.0;
	for (const auto& item : items) {
		if (capacity <= 0) break;
		if (item.weight <= capacity) {
			capacity -= item.weight; totalValue += item.value;
		} else {
			totalValue += item.value * ((double)capacity / item.weight);
			capacity = 0;
		}
	}
	return totalValue;
}

int main() {
	std::vector<Item> items = {{10, 60}, {20, 100}, {30, 120}};
	std::cout << fractionalKnapsack(50, items) << std::endl;
	return 0;
}
---
The original approach repeatedly scans the list to find the best item in O(N^2) time. Sorting items by value-per-weight density once allows a single-pass greedy selection in O(N log N) time, which is the standard optimal algorithm.

