output:
#include <iostream>
#include <vector>
#include <algorithm>

int minTaps(int n, std::vector<int>& ranges) {
	std::vector<int> maxReach(n + 1, 0);
	for (int i = 0; i <= n; i++) {
		int left = std::max(0, i - ranges[i]);
		int right = std::min(n, i + ranges[i]);
		maxReach[left] = std::max(maxReach[left], right);
	}
	int taps = 0, currEnd = 0, nextEnd = 0;
	for (int i = 0; i < n; i++) {
		nextEnd = std::max(nextEnd, maxReach[i]);
		if (i == currEnd) {
			taps++; currEnd = nextEnd;
		}
	}
	return currEnd >= n ? taps : -1;
}

int main() {
	std::vector<int> r = {3, 4, 1, 1, 0, 0};
	std::cout << minTaps(5, r) << std::endl;
	return 0;
}
---
The unoptimized version lacks a cohesive greedy strategy. The optimized approach pre-calculates the maximum reach for each start point and then uses a single-pass greedy jump (O(N) time) to cover the interval [0, n] with minimum taps.

