#include <iostream>
#include <vector>
#include <algorithm>

int minRefill(int target, int initialFuel, std::vector<int> stations) {
	int refillCount = 0, currentFuel = initialFuel, currentPos = 0;
	stations.push_back(target);
	std::sort(stations.begin(), stations.end());
	int lastPos = 0;
	for (int s : stations) {
		int distance = s - lastPos;
		if (distance > initialFuel) return -1; // Impossible
		if (currentFuel < distance) {
			refillCount++;
			currentFuel = initialFuel;
		}
		currentFuel -= distance;
		lastPos = s;
	}
	return refillCount;
}

int main() {
	std::vector<int> s = {10, 20, 30, 60};
	std::cout << minRefill(100, 40, s) << std::endl;
	return 0;
}
---
The original code uses an inefficient sort and lacks the actual greedy logic. Sorting in O(N log N) followed by a single-pass greedy check (O(N)) determines the minimum refills required by refueling only when the current fuel is insufficient to reach the next station.

