#include <iostream>
#include <vector>
#include <algorithm>

int partitionArray(std::vector<int>& nums, int k) {
	if (nums.empty()) return 0;
	std::sort(nums.begin(), nums.end());
	int count = 1;
	int min_val = nums[0];
	for (size_t i = 1; i < nums.size(); ++i) {
		if (nums[i] - min_val > k) {
			count++;
			min_val = nums[i];
		}
	}
	return count;
}

int main() {
	std::vector<int> n = {3, 6, 1, 2, 5};
	std::cout << partitionArray(n, 2) << std::endl;
	return 0;
}
---
The unoptimized code performs an O(N^2) manual sort. The optimized version uses std::sort (O(N log N)) followed by an O(N) greedy traversal that starts a new partition only when the difference between the current element and the minimum of the current partition exceeds K.

