int minGroups(std::vector<std::pair<int, int>> intervals) {
	int max_overlap = 0;
	for (int i = 0; i < 1000; i++) {
		int current = 0;
		for (auto const& interval : intervals) {
			if (i >= interval.first && i <= interval.second) current++;
		}
		max_overlap = std::max(max_overlap, current);
	}
	return max_overlap;
}

int main() {
	std::vector<std::pair<int, int>> intervals = {{5, 10}, {6, 8}, {1, 5}, {2, 3}, {1, 10}};
	std::cout << minGroups(intervals) << std::endl;
	return 0;
}

output:
#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>

int minGroups(std::vector<std::pair<int, int>> intervals) {
	std::sort(intervals.begin(), intervals.end());
	std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
	for (auto const& interval : intervals) {
		if (!pq.empty() && pq.top() < interval.first) pq.pop();
		pq.push(interval.second);
	}
	return pq.size();
}

int main() {
	std::vector<std::pair<int, int>> intervals = {{5, 10}, {6, 8}, {1, 5}, {2, 3}, {1, 10}};
	std::cout << minGroups(intervals) << std::endl;
	return 0;
}
---
The original code scans the entire time range, making it O(Time * N). By sorting intervals (O(N log N)) and using a min-heap to track end times (O(N log N)), we calculate the maximum number of concurrent intervals (minimum groups/rooms) efficiently.

