	std::cout << minCostToConnectRopes(r) << std::endl;
	return 0;
}

output:
#include <iostream>
#include <vector>
#include <queue>
#include <functional>

int minCostToConnectRopes(const std::vector<int>& ropes) {
	std::priority_queue<int, std::vector<int>, std::greater<int>> pq(ropes.begin(), ropes.end());
	int totalCost = 0;
	while (pq.size() > 1) {
		int first = pq.top(); pq.pop();
		int second = pq.top(); pq.pop();
		int cost = first + second;
		totalCost += cost;
		pq.push(cost);
	}
	return totalCost;
}

int main() {
	std::vector<int> r = {4, 3, 2, 6};
	std::cout << minCostToConnectRopes(r) << std::endl;
	return 0;
}
---
The unoptimized code re-sorts the vector in every iteration, leading to O(N^2 log N). Using a min-priority queue maintains the smallest elements at the top, allowing the greedy rope connection in O(N log N) total time.

