int maxUnits(std::vector<std::vector<int>> boxTypes, int truckSize) {
	int totalUnits = 0;
	while (truckSize > 0) {
		int bestIdx = -1, maxU = -1;
		for (size_t i = 0; i < boxTypes.size(); ++i) {
			if (boxTypes[i][1] > maxU && boxTypes[i][0] > 0) {
				maxU = boxTypes[i][1]; bestIdx = i;
			}
		}
		if (bestIdx == -1) break;
		int take = std::min(truckSize, boxTypes[bestIdx][0]);
		totalUnits += take * boxTypes[bestIdx][1];
		boxTypes[bestIdx][0] -= take; truckSize -= take;
	}
	return totalUnits;
}

int main() {
	std::vector<std::vector<int>> boxes = {{1, 3}, {2, 2}, {3, 1}};
	std::cout << maxUnits(boxes, 4) << std::endl;
	return 0;
}

