#include <iostream>
#include <vector>
#include <algorithm>

int maxUnits(std::vector<std::vector<int>>& boxTypes, int truckSize) {
	std::sort(boxTypes.begin(), boxTypes.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
		return a[1] > b[1];
	});
	int totalUnits = 0;
	for (auto& box : boxTypes) {
		int take = std::min(truckSize, box[0]);
		totalUnits += take * box[1];
		truckSize -= take;
		if (truckSize == 0) break;
	}
	return totalUnits;
}

int main() {
	std::vector<std::vector<int>> boxes = {{1, 3}, {2, 2}, {3, 1}};
	std::cout << maxUnits(boxes, 4) << std::endl;
	return 0;
}
---
The original code repeatedly scans the box list (O(N^2)). Sorting the box types by units per box in descending order allows for a single O(N) pass (after an O(N log N) sort), maximizing the profit greedily.

