int canCompleteCircuit(const std::vector<int>& gas, const std::vector<int>& cost) {
	int totalSurplus = 0, currentSurplus = 0, startIdx = 0;
	for (size_t i = 0; i < gas.size(); ++i) {
		int diff = gas[i] - cost[i];
		totalSurplus += diff;
		currentSurplus += diff;
		if (currentSurplus < 0) {
