int maxTwoEvents(std::vector<std::vector<int>>& events) {
	std::sort(events.begin(), events.end());
	int n = events.size(), res = 0, maxVal = 0;
	std::vector<int> suffixMax(n + 1, 0);
	for (int i = n - 1; i >= 0; --i) suffixMax[i] = std::max(suffixMax[i + 1], events[i][2]);
	for (int i = 0; i < n; ++i) {
