int minTaps(int n, const std::vector<int>& ranges) {
	std::vector<int> maxReach(n + 1, 0);
	for (int i = 0; i <= n; i++) {
		int start = std::max(0, i - ranges[i]);
		int end = std::min(n, i + ranges[i]);
		maxReach[start] = std::max(maxReach[start], end);
	}
	int taps = 0, currEnd = 0, nextEnd = 0;
	for (int i = 0; i < n; i++) {
		nextEnd = std::max(nextEnd, maxReach[i]);
		if (i == currEnd) {
			taps++; currEnd = nextEnd;
		}
	}
	return currEnd >= n ? taps : -1;
