int largestRectangleArea(const std::vector<int>& heights) {
	std::stack<int> s;
	int max_a = 0, n = heights.size();
	for (int i = 0; i <= n; i++) {
		int h = (i == n ? 0 : heights[i]);
		while (!s.empty() && heights[s.top()] >= h) {
