int minOperations(const std::vector<int>& nums, int x) {
	int target = std::accumulate(nums.begin(), nums.end(), 0) - x;
	if (target < 0) return -1;
	if (target == 0) return nums.size();
	int n = nums.size(), res = -1, cur = 0, i = 0;
